package com.therighthon.rnr.common.block;
import com.therighthon.rnr.RNRHelpers; import net.minecraft.core.BlockPos; import net.minecraft.core.Direction; import net.minecraft.server.level.ServerLevel; import net.minecraft.util.RandomSource; import net.minecraft.world.level.Level; import net.minecraft.world.level.LevelAccessor; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.Blocks; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.level.block.state.StateDefinition; import net.minecraft.world.level.block.state.properties.IntegerProperty;
public class CrackingWetConcretePathBlock extends WetConcretePathBlock { public static final int MAX_JOINT_DISTANCE=3; public static final IntegerProperty DISTANCE_X=RNRBlockStateProperties.DISTANCE_X,DISTANCE_Z=RNRBlockStateProperties.DISTANCE_Z; public CrackingWetConcretePathBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(DISTANCE_X,1).setValue(DISTANCE_Z,1));} protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(DISTANCE_X,DISTANCE_Z);} public void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){if(l.getBlockEntity(p) instanceof com.therighthon.rnr.common.blockentity.RNRTickCounterBlockEntity c&&c.getTicksSinceUpdate()>TICKS_TO_DRY)l.setBlockAndUpdate(p,Math.max(s.getValue(DISTANCE_X),s.getValue(DISTANCE_Z))>=3?getOutputStateCracked(s):getOutputState(s));} public void onPlace(BlockState s,Level l,BlockPos p,BlockState old,boolean moving){super.onPlace(s,l,p,old,moving);for(Direction d:Direction.Plane.HORIZONTAL){BlockPos q=p.relative(d);if(l.getBlockState(q).getBlock() instanceof CrackingWetConcretePathBlock)l.setBlockAndUpdate(q,l.getBlockState(q).setValue(d.getAxis()==Direction.Axis.X?DISTANCE_X:DISTANCE_Z,0));}} public BlockState getOutputStateCracked(BlockState in){if(in.is(RNRBlocks.WET_CONCRETE_ROAD.get()))return RNRBlocks.CRACKED_CONCRETE_ROAD.get().defaultBlockState();if(in.is(RNRBlocks.TRODDEN_WET_CONCRETE_ROAD.get()))return RNRBlocks.CRACKED_TRODDEN_CONCRETE_ROAD.get().defaultBlockState();return Blocks.AIR.defaultBlockState();} }
